-- Enrich the biographies of the artists currently included in SoundFusion.
-- Import this file into the existing db_web database; it changes only `about`.
SET NAMES utf8mb4;
USE `db_web`;

UPDATE `content`
SET `about` = CASE `companyname`
    WHEN 'The Weeknd' THEN 'Абель Тесфайе, известный как The Weeknd, — канадский певец и автор песен, чьё звучание выросло на пересечении альтернативного R&B, поп-музыки и электроники. Его ранние записи привлекли внимание тёмной атмосферой, мягкими мелодиями и характерным высоким вокалом. В более масштабных работах к этому звучанию добавились синтезаторы, выразительные ритмы и почти кинематографичные аранжировки. В центре его песен часто оказываются близость, одиночество, слава и цена собственных решений.'
    WHEN 'Playboi Carti' THEN 'Playboi Carti — американский рэпер из Атланты, известный экспериментальным подходом к трэпу и необычной вокальной манерой. Вместо плотного повествования он часто использует короткие фразы, повторы, интонации и адлибы как часть ритма. Его музыку отличают тяжёлые басы, резкие синтезаторы и намеренно шероховатый продакшн. Такой подход сделал его одним из самых узнаваемых представителей новой волны хип-хопа и заметно повлиял на звучание молодых рэп-артистов.'
    WHEN 'Kendrick Lamar' THEN 'Кендрик Ламар — американский рэпер и автор песен из Комптона, Калифорния. Его альбомы часто выстроены как цельные истории, в которых личный опыт переплетается с темами семьи, сообщества, идентичности и ответственности. Он свободно меняет ритм, голос и манеру исполнения, превращая каждую песню в отдельную сцену большого рассказа. Музыкальная основа его работ может соединять хип-хоп, джаз, фанк и соул, а тексты приглашают слушателя возвращаться к ним и находить новые смыслы.'
    WHEN 'Future' THEN 'Future — американский рэпер и автор песен из Атланты, сыгравший заметную роль в развитии мелодичного трэпа. Его узнаваемая подача сочетает рэп, напевные фразы и вокальные эффекты, а продакшн строится на упругих басах, синтезаторах и гипнотических повторениях. В песнях часто сталкиваются темы успеха, отношений, уязвимости и самоутверждения. Благодаря этому Future звучит одновременно как автор личных историй и как голос большого клубного хип-хопа.'
    WHEN 'Metro Boomin' THEN 'Metro Boomin — американский музыкальный продюсер и артист из Сент-Луиса, ставший одним из ключевых архитекторов современного трэп-звучания. Он строит биты вокруг точного ритма, глубокого баса и запоминающихся синтезаторных мотивов, уделяя большое внимание атмосфере и переходам между частями трека. В его работах минималистичные элементы могут соседствовать с оркестровыми и кинематографичными деталями. Metro также известен масштабными совместными проектами, где продакшн объединяет голоса разных исполнителей в цельную музыкальную историю.'
    WHEN 'Drake' THEN 'Дрейк — канадский рэпер, певец и автор песен из Торонто, который соединяет хип-хоп, R&B и поп-музыку. Его стиль строится на чередовании речитатива и мелодичных припевов, а тексты часто звучат как личный разговор о близости, амбициях, успехе и сомнениях. Он легко переключается между клубной энергией и сдержанными, задумчивыми песнями. Влияние Дрейка заметно в том, как современная популярная музыка смешивает рэп-вокал, пение и разные жанровые настроения.'
    WHEN 'Yeat' THEN 'Yeat — американский рэпер и автор песен, связанный с новой волной экспериментального трэпа. Его записи узнаются по обработанному вокалу, энергичным адлибам, тяжёлому басу и ярким синтезаторным звукам. Он часто превращает голос в ещё один инструмент аранжировки, используя тембр и ритм не меньше, чем сами слова. В его музыке сочетаются стремительный темп, нарочито необычные звуковые решения и запоминающиеся повторяющиеся мотивы.'
    WHEN 'Don Toliver' THEN 'Don Toliver — американский певец и рэпер из Хьюстона, работающий на стыке мелодичного хип-хопа и R&B. Его гибкий вокал легко переходит от спокойного напева к насыщенным эффектами фразам, а продакшн часто создаёт просторную, ночную атмосферу. В песнях важны мелодия, настроение и плавное взаимодействие голоса с басом и синтезаторами. Такой подход позволяет ему одинаково уверенно звучать и в личных композициях, и в масштабных совместных треках.'
    WHEN 'Tyler, The Creator' THEN 'Тайлер, зе Криэйтор — американский рэпер, продюсер и автор песен из Лос-Анджелеса. Он известен тем, что самостоятельно формирует значительную часть музыкального мира своих проектов и свободно меняет направление от альбома к альбому. В его хип-хопе встречаются соул, джаз, альтернативный поп и R&B, а живые гармонии соседствуют с неожиданными синтезаторами и ритмами. Его тексты могут быть ироничными и провокационными, но в них также много размышлений о взрослении, привязанности и поиске себя.'
    WHEN 'Ye' THEN 'Ye — американский рэпер, продюсер и дизайнер из Чикаго, чьи работы охватывают хип-хоп, поп и экспериментальную электронную музыку. Как продюсер, он прославился вниманием к семплам, необычным сочетаниям тембров и смелой работе с аранжировкой. Его звучание менялось от лаконичных битов и соул-фрагментов до масштабных синтезаторных и хоровых композиций. Эта постоянная смена подхода сделала его творчество предметом обсуждения как музыкальных экспериментов, так и влияния на эстетику современной поп-культуры.'
    WHEN 'A$AP Rocky' THEN 'A$AP Rocky — американский рэпер из Гарлема, Нью-Йорк, известный атмосферным звучанием и вниманием к визуальному образу. В его музыке нью-йоркский хип-хоп соединяется с психоделическими эффектами, южными музыкальными влияниями и расслабленной подачей. Он часто работает с контрастом между тяжёлым басом и воздушными, размытыми мелодиями. Помимо музыки, Rocky участвует в создании клипов и модных проектов, поэтому его артистический образ складывается сразу из звука, изображения и стиля.'
    WHEN 'Radiohead' THEN 'Radiohead — британская группа, чьё творчество прошло путь от альтернативного рока к широкому спектру электронных и экспериментальных форм. В их песнях гитарные партии могут соседствовать с петлями, семплами, фортепиано и необычными ритмическими решениями. Группа стремится менять звучание от релиза к релизу, сохраняя внимание к сильной мелодии и выразительной атмосфере. Среди постоянных тем — отчуждение, тревога, влияние технологий и ощущение перемен в окружающем мире.'
    WHEN 'Ariana Grande' THEN 'Ариана Гранде — американская певица и автор песен из Флориды, известная гибким вокалом, широким диапазоном и выразительными мелодическими украшениями. Её поп-музыка соединяет современный R&B, танцевальные ритмы и многослойные вокальные гармонии. В одних песнях на первый план выходит уверенная, энергичная подача, в других — более тихий и уязвимый рассказ о любви, взрослении и личных границах. Её голос часто становится главным инструментом аранжировки, вокруг которого строится весь трек.'
    WHEN 'SZA' THEN 'SZA — американская певица и автор песен, соединяющая альтернативный R&B, соул и поп. Её вокал звучит естественно и свободно, а аранжировки могут переходить от мягких гитар и камерных клавиш к плотным электронным ритмам. В текстах она открыто говорит о самооценке, отношениях, ревности и противоречивых чувствах, не стараясь представить эмоции однозначными. Благодаря этой честности её песни воспринимаются как личные заметки, в которых слушатели узнают собственный опыт.'
    WHEN 'Billie Eilish' THEN 'Билли Айлиш — американская певица и автор песен из Лос-Анджелеса, сформировавшая узнаваемый стиль на контрасте тихого вокала и выразительной электронной основы. Вместе с братом и соавтором Финнеасом она работает с близкими, почти шёпотными интонациями, необычными звуковыми деталями и точными паузами. Её музыка может быть одновременно минималистичной и кинематографичной, а песни обращаются к темам взросления, тревоги, отношений и самоощущения. Особое внимание к визуальному языку дополняет музыкальные истории, не подменяя их.'
    WHEN 'Travis Scott' THEN 'Трэвис Скотт — американский рэпер и продюсер из Хьюстона, известный плотным, атмосферным подходом к хип-хоп-продакшну. Его песни часто объединяют обработанный вокал, гулкие басы, многослойные синтезаторы и резкие смены динамики. Вместо прямолинейного повествования он нередко строит треки как последовательность ярких звуковых сцен, где важны тембр, энергия и общий масштаб. В его музыке можно услышать влияние южного рэпа, психоделической электроники и современной фестивальной культуры.'
    WHEN 'J. Cole' THEN 'Джей Коул — американский рэпер, продюсер и автор песен из Фейетвилла, Северная Каролина. Его стиль опирается на ясное повествование и личные наблюдения о выборе, амбициях, семье и жизни в обществе. В музыкальной основе часто встречаются сдержанные биты, тёплые семплы и ритмы, которые оставляют достаточно пространства для текста. Коул также продюсирует собственные работы, поэтому лирика и музыкальная подача в его проектах обычно складываются в единое целое.'
    WHEN 'Kaytranada' THEN 'Kaytranada — гаитянско-канадский диджей и музыкальный продюсер, создающий танцевальную музыку на пересечении хауса, хип-хопа, фанка и R&B. Его продакшн узнаётся по упругому груву, мягкой басовой линии и ритмам, которые звучат непринуждённо, но точно собраны. В инструментальных треках он раскрывает собственные мелодические идеи, а в совместных работах оставляет артистам пространство для вокала. Музыка Kaytranada одинаково хорошо подходит для внимательного прослушивания и для движения.'
    ELSE `about`
END
WHERE `companyname` IN (
    'The Weeknd', 'Playboi Carti', 'Kendrick Lamar', 'Future', 'Metro Boomin', 'Drake',
    'Yeat', 'Don Toliver', 'Tyler, The Creator', 'Ye', 'A$AP Rocky', 'Radiohead',
    'Ariana Grande', 'SZA', 'Billie Eilish', 'Travis Scott', 'J. Cole', 'Kaytranada'
);
